#!/usr/bin/env python3
import base64, os
d = "/home/admin/yuzhou-inquiry/public"
os.makedirs(d, exist_ok=True)
data = {
  'cat-wood-medals.jpg': '',
  'cat-inner-carving.jpg': '',
  'cat-jewelry-boxes.jpg': '',
  'cat-perfume.jpg': '',
  'cat-figurines.jpg': '',
  'cat-smoking.jpg': '',
  'cat-candles.jpg': '',
}
for name, b64 in data.items():
    path = os.path.join(d, name)
    with open(path, "wb") as f:
        f.write(base64.b64decode(b64))
    print(f"OK: {name} ({os.path.getsize(path)} bytes)")
print(f'Batch 2 done!')
